import json
motif=[[8,9,8,9,6,9,8,7],[9,9,9,8,8,3,9,9]]
out=[]
for pair in range(2):
 for rr in range(2):
  row=[]
  for tile in range(3):
   row += motif[rr]
   if tile<2: row.append(4)
  out.append(row)
 if pair==0: out.append([4]*26)
assert len(out)==5 and all(len(r)==26 for r in out)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))
